#requires -Version 7
# score-t.ps1 — 按 cat=T综合对抗 单独聚合 T8-T11 得分（不进混淆矩阵）
$ErrorActionPreference = 'Stop'
$dir = Split-Path -Parent $MyInvocation.MyCommand.Path
$resDir = Join-Path $dir 'results'
$doc = Get-Content (Join-Path $dir 'tasks-master.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$taskMap = @{}; foreach ($t in $doc.tasks) { $taskMap[$t.id] = $t }
$rows = (Get-Content (Join-Path $resDir 'bench-full.json') -Raw -Encoding UTF8 | ConvertFrom-Json).rows

$ids = @('T8','T9','T10','T11')
$out = @()
foreach ($r in $rows) {
  if ($ids -notcontains $r.task) { continue }
  if ($r.error) { $out += [pscustomobject]@{ model=$r.model; task=$r.task; error=$r.error; total=0; ms=$r.ms }; continue }
  $t = $taskMap[$r.task]
  $parsed = $null
  try { $parsed = $r.raw | ConvertFrom-Json } catch { }
  if (-not $parsed -or -not $parsed.route) {
    $out += [pscustomobject]@{ model=$r.model; task=$r.task; format_error=$true; tool=0; comp=0; route=0; eff=0; total=0; ms=$r.ms }
    continue
  }
  $routeScore = if ($parsed.route -eq $t.route_expect) { 1.0 } else { 0.0 }
  $steps = @($parsed.steps) | Where-Object { $_ -and $_.tool }
  $toolScore = 0.0
  if ($steps.Count -gt 0) {
    $sum = 0.0
    foreach ($s in $steps) {
      if ($t.optimal_tools -contains $s.tool) { $sum += 1.0 }
      elseif ($t.acceptable_tools -contains $s.tool) { $sum += 0.6 }
    }
    $toolScore = $sum / [Math]::Max(1, $steps.Count)
  }
  $text = (@($parsed.analysis) + @($steps | ForEach-Object { $_.intent }) + @($parsed.notes)) -join ' '
  $hit = 0; $req = @($t.required).Count
  foreach ($pat in $t.required) { if ($text -match $pat) { $hit++ } }
  $compScore = if ($req -gt 0) { $hit / $req } else { 1.0 }
  $effScore = if ($steps.Count -ge 1) { [Math]::Min(1.0, $t.optimal_steps / $steps.Count) } else { 0.0 }
  $total = [math]::Round(0.35*$toolScore + 0.25*$compScore + 0.25*$routeScore + 0.15*$effScore, 3)
  $out += [pscustomobject]@{ model=$r.model; task=$r.task; route_got=$parsed.route; n_steps=$steps.Count
    tool=[math]::Round($toolScore,2); comp=[math]::Round($compScore,2); routeS=$routeScore
    eff=[math]::Round($effScore,2); total=$total; ms=$r.ms }
}
$out | ConvertTo-Json -Depth 5 | Set-Content (Join-Path $resDir 'score-t.json') -Encoding UTF8

Write-Output '=== T8-T11 按模型汇总（均值，cat=T综合对抗） ==='
$out | Where-Object { -not $_.error } | Group-Object model | ForEach-Object {
  $g = $_.Group
  [pscustomobject]@{
    model = $_.Name; n = $g.Count
    fmt_err = @($g | Where-Object { $_.format_error }).Count
    err = @($g | Where-Object { $_.error }).Count
    tool = [math]::Round(($g | Measure-Object tool -Average).Average, 2)
    comp = [math]::Round(($g | Measure-Object comp -Average).Average, 2)
    route = [math]::Round(($g | Measure-Object routeS -Average).Average, 2)
    eff = [math]::Round(($g | Measure-Object eff -Average).Average, 2)
    TOTAL = [math]::Round(($g | Measure-Object total -Average).Average, 3)
    avg_ms = [math]::Round(($g | Measure-Object ms -Average).Average, 0)
  }
} | Sort-Object TOTAL -Descending | Format-Table -AutoSize | Out-String -Width 160

Write-Output '=== 逐题得分矩阵（行=model, 列=T8..T11） ==='
$out | Where-Object { -not $_.error } | Group-Object model | ForEach-Object {
  $m = $_.Name
  $cells = foreach ($id in $ids) { $row = $_.Group | Where-Object { $_.task -eq $id }; if ($row) { $row.total } else { '-' } }
  "{0,-32} {1,-6} {2,-6} {3,-6} {4,-6}" -f $m, $cells[0], $cells[1], $cells[2], $cells[3]
}
Write-Output '=== 错误行 ==='
